using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RepeatedExerciseTests
{
    static WorldSession Start()=>NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:combat/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static WorldSession Ready(){var s=Start();Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);return s;}
    static void Permit(WorldSession s){Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);}
    static void Modern(WorldSession s,NewMilitaryAction a){var r=s.DecideNewMilitary(Input(s,a) with{ExercisePolicy=NewGameMilitary.RepeatedExerciseContract,MotionContract=a==NewMilitaryAction.CombatStart?NewGameMilitary.RoutContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static WorldSession Authorized(){var s=Ready();Modern(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);return s;}
    static void Restore(WorldSession s,long until){var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));At(s,until);At(c,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void TwoContactsKeepPreviousLossesAndFoodWithoutDoubleTick(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);long first=s.Seconds;long food=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;At(s,first+1);Send(s,NewMilitaryAction.CombatEnd);var w=s.DiagnosticSnapshot();int men=NewGameMilitary.TotalStrength(w,s.Seconds);Assert.Equal(90,men);var old=ContractJson.CanonicalHash(NewGameMilitary.CombatLosses(w,s.Seconds));Modern(s,NewMilitaryAction.CombatStart);Assert.Equal(men,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));Assert.Equal(men,NewGameMilitary.ExerciseState(s.DiagnosticSnapshot(),s.Seconds).Opponents.Sum(u=>u.Soldiers));At(s,first+2);w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.TotalStrength(w,s.Seconds)<men);Assert.Equal(190,food-NewGameMilitary.View(w).Carry);Assert.Equal(old,ContractJson.CanonicalHash(NewGameMilitary.CombatLosses(w,first+1)));Send(s,NewMilitaryAction.CombatEnd);Restore(s,s.Seconds+3);}
    [Fact]public void OldSingleContactPermissionCannotBeSilentlyExtended(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{ExercisePolicy=NewGameMilitary.RepeatedExerciseContract,MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void RepeatedVersionStillRequiresOpenedPhysicalPermission(){var s=Ready();Modern(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Open(s);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission);var body=ContractJson.Read<MilitaryNotice>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==e.Message).Body));Assert.Equal(NewGameMilitary.RepeatedExerciseContract,body.Combat!.Contract);}
    [Fact]public void QuotedRepeatPermissionPreservesPolicyWithoutOpeningOriginal(){var s=Ready();Modern(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);var original=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission).Message;Send(s,NewMilitaryAction.Inquire);At(s,s.Seconds+2);var reply=s.DiagnosticSnapshot().NewMilitary!.Events.Last(e=>e.Effect==MilitaryEffect.StatusSent).Message;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(reply),s.Revision).Code);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,original,s.PlayerControl.Value));Restore(s,s.Seconds+1);}
    [Fact]public void SecondRoutAndRegroupKeepDistinctLifetimeRecords(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);long first=s.Seconds;At(s,first+10);var w=s.DiagnosticSnapshot();Assert.NotEmpty(w.NewMilitary!.Rout!.Retreats);long regroup=w.NewMilitary.Rout.Arrivals.Max(a=>a.At)+NewGameMilitary.RegroupSeconds;At(s,regroup+1);Assert.False(NewGameMilitary.RoutActive(s.DiagnosticSnapshot()));var before=s.DiagnosticSnapshot().NewMilitary!.Rout!;int men=NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds);Modern(s,NewMilitaryAction.CombatStart);Assert.Equal(men,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));Assert.All(NewGameMilitary.OwnCombatReport(s.DiagnosticSnapshot(),s.Seconds),u=>Assert.Equal(NewGameMilitary.RegroupMorale,u.Morale));At(s,s.Seconds+5);w=s.DiagnosticSnapshot();Assert.Equal(2,w.NewMilitary!.Rout!.Retreats.Length);Assert.Equal(6,w.NewMilitary.Rout.Arrivals.Length);Assert.Equal(3,w.NewMilitary.Rout.Regroups.Length);Assert.True(NewGameMilitary.RoutActive(w));Assert.All(before.Retreats,r=>Assert.Contains(w.NewMilitary.Rout.Retreats,x=>x.Order==r.Order&&ContractJson.CanonicalHash(x)==ContractJson.CanonicalHash(r)));long second=w.NewMilitary.Rout.Arrivals.Max(a=>a.At)+NewGameMilitary.RegroupSeconds;Restore(s,second+1);w=s.DiagnosticSnapshot();Assert.Equal(6,w.NewMilitary!.Rout!.Regroups.Length);Assert.False(NewGameMilitary.RoutActive(w));Assert.True(NewGameMilitary.TotalStrength(w,s.Seconds)<men);}
    [Fact]public void RepeatedPermissionExpiryStillBlocksNewEpisode(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);At(s,s.Seconds+NewGameMilitary.CombatPermitDuration);Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Restore(s,s.Seconds+1);}
    [Fact]public void RegroupMustActuallyFinishBeforeAnotherEpisode(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+10);var x=s.DiagnosticSnapshot().NewMilitary!.Rout!;long regroup=x.Arrivals.Max(a=>a.At)+NewGameMilitary.RegroupSeconds;At(s,regroup-1);Assert.True(NewGameMilitary.RoutActive(s.DiagnosticSnapshot()));Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));At(s,regroup);Assert.False(NewGameMilitary.RoutActive(s.DiagnosticSnapshot()));Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Restore(s,s.Seconds+1);}
    [Fact]public void OldInputShapeAndHistoricalLossesRemainAfterOptIn(){var s=Ready();Permit(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);var w=s.DiagnosticSnapshot();long at=s.Seconds;string hits=ContractJson.CanonicalHash(NewGameMilitary.CombatLosses(w,at));Assert.DoesNotContain("ExercisePolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Send(s,NewMilitaryAction.Recall);var order=s.DiagnosticSnapshot().NewMilitary!.Orders.Last();At(s,order.Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);Open(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);Modern(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);Assert.Equal(hits,ContractJson.CanonicalHash(NewGameMilitary.CombatLosses(s.DiagnosticSnapshot(),at)));Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Assert.Equal(hits,ContractJson.CanonicalHash(NewGameMilitary.CombatLosses(s.DiagnosticSnapshot(),at)));Restore(s,s.Seconds+2);}
    [Fact]public void PermissionFromPriorCaseCannotAuthorizeFreshEpisode(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Send(s,NewMilitaryAction.Recall);var o=s.DiagnosticSnapshot().NewMilitary!.Orders.Last();At(s,o.Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);Open(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);Assert.False(NewGameMilitary.ExerciseVisible(s.DiagnosticSnapshot()));Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Modern(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);Assert.True(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Restore(s,s.Seconds+1);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void UnknownOrMisplacedExercisePolicyIsAtomic(int kind){var s=Authorized();var i=Input(s,kind==1?NewMilitaryAction.Hold:NewMilitaryAction.CombatStart) with{ExercisePolicy=kind==0?"unknown":NewGameMilitary.RepeatedExerciseContract,MotionContract=kind==0?NewGameMilitary.RoutContract:null};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)]public void ForgedEpisodeInputOrPermissionContractIsRejected(int kind){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Modern(s,NewMilitaryAction.CombatStart);var w=s.DiagnosticSnapshot();if(kind==0){int n=Array.FindLastIndex(w.NewMilitary!.Requests,q=>q.Input.Action==NewMilitaryAction.CombatStart);var q=w.NewMilitary.Requests[n];w.NewMilitary.Requests[n]=q with{Input=q.Input with{ExercisePolicy=null}};}else{var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.CombatPermission);int n=Array.FindIndex(w.Messaging.Messages,m=>m.Id==e.Message);var m=w.Messaging.Messages[n];var body=ContractJson.Read<MilitaryNotice>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages[n]=m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(body with{Combat=body.Combat! with{Contract=NewGameMilitary.CombatContract}}))};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void EveryContactBoundaryRestoresSameTwoEpisodeFuture(int phase){var s=Authorized();if(phase>0){Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);}if(phase>1)Modern(s,NewMilitaryAction.CombatStart);if(phase>2)At(s,s.Seconds+1);if(phase>3)Send(s,NewMilitaryAction.CombatEnd);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c}){if(phase==0){Modern(x,NewMilitaryAction.CombatStart);At(x,x.Seconds+1);Send(x,NewMilitaryAction.CombatEnd);}if(phase<2)Modern(x,NewMilitaryAction.CombatStart);if(phase<3)At(x,x.Seconds+1);if(phase<4)Send(x,NewMilitaryAction.CombatEnd);At(x,x.Seconds+2);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void ActiveContactCannotBeRestartedToResetItsDamage(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+1);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.False(NewGameMilitary.CanStartCombat(s.DiagnosticSnapshot(),NewGameMilitary.RepeatedExerciseContract));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{ExercisePolicy=NewGameMilitary.RepeatedExerciseContract,MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void SyntheticOpponentsUseDistinctEpisodeIdsWhileRealUnitsPersist(){var s=Authorized();Modern(s,NewMilitaryAction.CombatStart);var first=NewGameMilitary.ExerciseState(s.DiagnosticSnapshot(),s.Seconds).Opponents.Select(u=>u.Unit).ToArray();var own=s.DiagnosticSnapshot().Units.Select(u=>u.Id).ToArray();At(s,s.Seconds+1);Send(s,NewMilitaryAction.CombatEnd);Modern(s,NewMilitaryAction.CombatStart);var second=NewGameMilitary.ExerciseState(s.DiagnosticSnapshot(),s.Seconds).Opponents.Select(u=>u.Unit).ToArray();Assert.Empty(first.Intersect(second));Assert.Equal(own,s.DiagnosticSnapshot().Units.Select(u=>u.Id).ToArray());At(s,s.Seconds+1);var hits=NewGameMilitary.CombatLosses(s.DiagnosticSnapshot(),s.Seconds);Assert.Contains(hits,h=>first.Contains(h.Unit));Assert.Contains(hits,h=>second.Contains(h.Unit));Restore(s,s.Seconds+1);}
}
